import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    idx = 0
    M = int(data[idx]); idx += 1
    N = int(data[idx]); idx += 1

    mat1 = []
    for _ in range(M):
        row = []
        for _ in range(N):
            row.append(int(data[idx])); idx += 1
        mat1.append(row)

    mat2 = []
    for _ in range(M):
        row = []
        for _ in range(N):
            row.append(int(data[idx])); idx += 1
        mat2.append(row)

    result = []
    for i in range(M):
        row = []
        for j in range(N):
            row.append(mat1[i][j] + mat2[i][j])
        result.append(row)

    for i in range(M):
        print(' '.join(str(result[i][j]) for j in range(N)))

if __name__ == "__main__":
    main()
